    return 0;
}

extern "C" int ds4_gpu_preload_q4_expert_tables(const void *model_map, uint64_t model_size,
                                                uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
                                                uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
                                                uint32_t n_total_expert) {
    (void)model_map;
    (void)model_size;
    (void)gate_offset;
    (void)up_offset;
    (void)down_offset;
    (void)gate_expert_bytes;
    (void)down_expert_bytes;
    (void)n_total_expert;
    return 1;
}

extern "C" int ds4_gpu_set_model_map_spans(
        const void *model_map,
        uint64_t model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t count,
        uint64_t max_tensor_bytes) {
    (void)max_tensor_bytes;
    if (!model_map || model_size == 0 || !offsets || !sizes || count == 0) return 0;
    for (uint32_t i = 0; i < count; i++) {
        if (offsets[i] > model_size ||
            sizes[i] == 0 ||
            sizes[i] > model_size - offsets[i]) {
            return 0;
        }
    }
    if (!cuda_model_set_host_map(model_map, model_size)) return 0;

    if (getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL) {
        for (uint32_t i = 0; i < count; i++) {
            (void)cuda_model_prefetch_range(model_map, model_size, offsets[i], sizes[i]);
        }
    }
    return 1;
}

extern "C" int ds4_gpu_set_model_fd_for_map(int fd, const void *model_map) {
    g_model_fd = fd;
    g_model_fd_host_base = model_map;
    g_model_file_size = 0;
    if (g_model_direct_fd >= 0) {
        (void)close(g_model_direct_fd);
        g_model_direct_fd = -1;
    }
    g_model_direct_align = 1;
    if (fd >= 0) {
        struct stat st;
        if (fstat(fd, &st) == 0 && st.st_size > 0) {
            g_model_file_size = (uint64_t)st.st_size;
            if (st.st_blksize > 1) g_model_direct_align = (uint64_t)st.st_blksize;
        }
#if defined(__linux__) && defined(O_DIRECT)
        if (getenv("DS4_CUDA_NO_DIRECT_IO") == NULL) {
            char proc_path[64];
            snprintf(proc_path, sizeof(proc_path), "/proc/self/fd/%d", fd);
            int direct_fd = open(proc_path, O_RDONLY | O_DIRECT);
            if (direct_fd >= 0) {
                g_model_direct_fd = direct_fd;
                if (g_model_direct_align < 512) g_model_direct_align = 512;
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA model direct I/O enabled (align=%llu)\n",
                            (unsigned long long)g_model_direct_align);
                }
            } else if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                fprintf(stderr, "ds4: CUDA model direct I/O unavailable: %s\n", strerror(errno));
            }
        }
#endif
    }
    return 1;
}

extern "C" int ds4_gpu_set_model_fd(int fd) {
    return ds4_gpu_set_model_fd_for_map(fd, g_model_host_base);
}

extern "C" int ds4_gpu_cache_model_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return 0;
    if (cuda_model_range_is_cached(model_map, offset, bytes)) return 1;

    const char *ptr = cuda_model_range_ptr(model_map, offset, bytes, label ? label : "model_tensor");
    if (!ptr || !cuda_model_range_is_cached(model_map, offset, bytes)) {
        if (!g_model_mapping_failure_notice_printed) {
            fprintf(stderr,
                    "ds4: CUDA failed to prepare model tensor spans for device access\n");
            g_model_mapping_failure_notice_printed = 1;
        }
        return 0;
    }
    return 1;
}

/* Storage-neutral sm_120 IQ2 layout transform.  The GGUF and host mapping stay
 * in canonical [expert][row][K256] order.  Each already-cached HBM expert is
 * copied through one small scratch buffer and scattered back as:
 *   [K256][all row d values][ib32][all row 8-byte aux values].
 * The hot N16 kernel can then fetch its 16 rows from contiguous sectors. */
__global__ static void iq2_xxs_expert_plane_repack_kernel(
        char *dst,
        const cuda_block_iq2_xxs *src,
        uint32_t n_rows,
        uint32_t n_blocks) {
    const uint32_t row = blockIdx.x * blockDim.x + threadIdx.x;
    const uint32_t kb = blockIdx.y;
    if (row >= n_rows || kb >= n_blocks) return;

    const cuda_block_iq2_xxs *block = src + (uint64_t)row * n_blocks + kb;
    const uint64_t kb_stride = (uint64_t)n_rows * sizeof(*block);
    char *plane = dst + (uint64_t)kb * kb_stride;
    ((uint16_t *)plane)[row] = block->d;

    const uint64_t d_bytes = (uint64_t)n_rows * sizeof(uint16_t);
    const uint64_t ib_stride = (uint64_t)n_rows * 4u * sizeof(uint16_t);
    #pragma unroll
    for (uint32_t ib32 = 0; ib32 < 8u; ib32++) {
        uint16_t *aux = (uint16_t *)(plane + d_bytes +
            (uint64_t)ib32 * ib_stride) + (uint64_t)row * 4u;
        #pragma unroll
        for (uint32_t i = 0; i < 4u; i++) {
            aux[i] = block->qs[ib32 * 4u + i];
        }
    }
}

extern "C" int ds4_gpu_repack_iq2_xxs_expert_planes(
        const void *model_map,
        uint64_t model_size,
        uint64_t offset,
        uint64_t bytes,
        uint32_t n_expert,
        uint32_t n_rows,
        uint32_t n_blocks) {
    if (!model_map || bytes == 0 || n_expert == 0 || n_rows == 0 ||
        n_blocks != 16u || offset > model_size || bytes > model_size - offset) {
        return 0;
    }
    const uint64_t expert_bytes =
        (uint64_t)n_rows * n_blocks * sizeof(cuda_block_iq2_xxs);
    if (expert_bytes == 0 || expert_bytes > SIZE_MAX ||
        (uint64_t)n_expert > UINT64_MAX / expert_bytes ||
        bytes != (uint64_t)n_expert * expert_bytes) {
        return 0;
    }

    const int plane_state = cuda_iq2_expert_plane_range_state(
        model_map, offset, bytes);
    if (plane_state == 1) return 1;
    if (plane_state != 0) {
        fprintf(stderr,
                "ds4: IQ2 expert-plane transform overlaps an incompatible "
                "registered range\n");
        return 0;
    }

    char *tensor = (char *)cuda_model_range_ptr(
        model_map, offset, bytes, "iq2_expert_planes");
    if (!tensor) return 0;
    cudaPointerAttributes attr = {};
    cudaError_t err = cudaPointerGetAttributes(&attr, tensor);
    if (err != cudaSuccess || attr.type != cudaMemoryTypeDevice) {
        fprintf(stderr,
                "ds4: IQ2 expert-plane transform requires a device-resident "
                "weight cache\n");
        (void)cudaGetLastError();
        return 0;
    }

    cuda_block_iq2_xxs *scratch = NULL;
    err = cudaMalloc((void **)&scratch, (size_t)expert_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: IQ2 expert-plane scratch allocation failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    int ok = 1;
    const dim3 grid((n_rows + 255u) / 256u, n_blocks, 1u);
    for (uint32_t expert = 0; expert < n_expert && ok; expert++) {
        char *dst = tensor + (uint64_t)expert * expert_bytes;
        err = cudaMemcpyAsync(scratch, dst, (size_t)expert_bytes,
                              cudaMemcpyDeviceToDevice, 0);
        if (err != cudaSuccess) {
            ok = 0;
            break;
        }
        iq2_xxs_expert_plane_repack_kernel<<<grid, 256>>>(
            dst, scratch, n_rows, n_blocks);
        if (cudaGetLastError() != cudaSuccess) ok = 0;
    }
    if (ok) {
        ok = cuda_ok(cudaStreamSynchronize(0),
                     "IQ2 expert-plane transform sync");
    }
    (void)cudaFree(scratch);
    if (ok) {
        ok = cuda_iq2_expert_plane_range_register(
            model_map, offset, bytes);
    }
    return ok;
}

extern "C" int ds4_gpu_cache_q8_f16_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, uint64_t in_dim, uint64_t out_dim, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return 0;
    const char *cache_label = label ? label : "q8_0";
    if (getenv("DS4_CUDA_Q8_F32_PRELOAD") != NULL &&
        cuda_q8_f32_cache_allowed(cache_label, in_dim, out_dim)) {
        if (cuda_q8_f32_ptr(model_map, offset, bytes, in_dim, out_dim, cache_label)) return 1;
        return 1;
    }
    if (!cuda_q8_f16_cache_allowed(cache_label, in_dim, out_dim)) return 1;
    if (cuda_q8_f16_ptr(model_map, offset, bytes, in_dim, out_dim, cache_label)) return 1;
    return 1;
}

extern "C" void ds4_gpu_print_memory_report(const char *label) {
    size_t free_b = 0, total_b = 0;
    (void)cudaMemGetInfo(&free_b, &total_b);
    fprintf(stderr, "ds4: CUDA memory report %s: free %.2f MiB total %.2f MiB\n",
            label ? label : "", (double)free_b / 1048576.0, (double)total_b / 1048576.0);
}

extern "C" void ds4_gpu_set_quality(bool quality) {
    g_quality_mode = quality ? 1 : 0;
    if (g_cublas_ready) {
        const cublasMath_t math_mode =
            (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
                ? CUBLAS_DEFAULT_MATH
                : CUBLAS_TF32_TENSOR_OP_MATH;
        (void)cublasSetMathMode(g_cublas, math_mode);
    }
}

