extern "C" int ds4_gpu_indexer_topk_tensor(
        ds4_gpu_tensor       *selected,
        const ds4_gpu_tensor *scores,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k) {
    if (!selected || !scores || n_comp == 0 || n_tokens == 0 || top_k == 0 ||
        top_k > n_comp ||
        scores->bytes < (uint64_t)n_tokens * n_comp * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * top_k * sizeof(uint32_t)) {
        return 0;
    }
    if (top_k == 512u && n_comp <= 1024u &&
        getenv("DS4_CUDA_NO_TOPK1024") == NULL) {
        if (getenv("DS4_CUDA_INDEXER_TOPK_CUB_EXACT") != NULL) {
            return indexer_topk_cub_exact_launch<1024u, 8u>(
                    (uint32_t *)selected->ptr,
                    NULL,
                    (const float *)scores->ptr,
                    n_comp,
                    n_tokens);
        }
        if (getenv("DS4_CUDA_INDEXER_TOPK_CUB_EXACT_TIMING") != NULL &&
            !indexer_topk_cub_exact_launch<1024u, 8u>(
                    (uint32_t *)selected->ptr,
                    (uint32_t *)selected->ptr,
                    (const float *)scores->ptr,
                    n_comp,
                    n_tokens)) {
            return 0;
        }
        indexer_topk_1024_kernel<<<n_tokens, 1024>>>((uint32_t *)selected->ptr,
                                                     (const float *)scores->ptr,
                                                     n_comp, n_tokens, top_k);
        return cuda_ok(cudaGetLastError(), "indexer topk 1024 launch");
    }
    if (top_k == 512u && n_comp <= 2048u &&
        getenv("DS4_CUDA_NO_TOPK2048") == NULL) {
        if (getenv("DS4_CUDA_INDEXER_TOPK_CUB_EXACT") != NULL) {
            return indexer_topk_cub_exact_launch<2048u, 16u>(
                    (uint32_t *)selected->ptr,
                    NULL,
                    (const float *)scores->ptr,
                    n_comp,
                    n_tokens);
        }
        if (getenv("DS4_CUDA_INDEXER_TOPK_CUB_EXACT_TIMING") != NULL &&
            !indexer_topk_cub_exact_launch<2048u, 16u>(
                    (uint32_t *)selected->ptr,
                    (uint32_t *)selected->ptr,
                    (const float *)scores->ptr,
                    n_comp,
                    n_tokens)) {
            return 0;
        }
        indexer_topk_pow2_kernel<2048><<<n_tokens, 1024>>>((uint32_t *)selected->ptr,
                                                           (const float *)scores->ptr,
                                                           n_comp, n_tokens, top_k);
        return cuda_ok(cudaGetLastError(), "indexer topk 2048 launch");
    }
    if (top_k == 512u && n_comp <= 4096u &&
        getenv("DS4_CUDA_NO_TOPK2048") == NULL) {
        if (n_comp == 4096u) {
            using TopkCubSort = cub::BlockRadixSort<uint64_t, 512, 16>;
            const int smem = (int)sizeof(typename TopkCubSort::TempStorage);
            int dev = 0;
            int max_optin_smem = 0;
            cudaError_t attr_err = cudaGetDevice(&dev);
            if (attr_err == cudaSuccess) {
                attr_err = cudaDeviceGetAttribute(&max_optin_smem,
                                                  cudaDevAttrMaxSharedMemoryPerBlockOptin,
                                                  dev);
            }
            if (attr_err == cudaSuccess && max_optin_smem >= smem) {
                attr_err = cudaFuncSetAttribute(indexer_topk_8192_cub_kernel,
                                                cudaFuncAttributeMaxDynamicSharedMemorySize,
                                                smem);
                if (attr_err == cudaSuccess) {
                    indexer_topk_8192_cub_kernel<<<n_tokens, 512, (size_t)smem>>>((uint32_t *)selected->ptr,
                                                                                 (const float *)scores->ptr,
                                                                                 n_comp, n_tokens, top_k);
                    return cuda_ok(cudaGetLastError(), "indexer topk 4096 cub launch");
                }
            }
        }
        indexer_topk_pow2_kernel<4096><<<n_tokens, 1024>>>((uint32_t *)selected->ptr,
                                                           (const float *)scores->ptr,
                                                           n_comp, n_tokens, top_k);
        return cuda_ok(cudaGetLastError(), "indexer topk 4096 launch");
    }
    if (top_k == 512u && n_comp <= 8192u &&
        getenv("DS4_CUDA_NO_TOPK2048") == NULL &&
        getenv("DS4_CUDA_NO_TOPK8192") == NULL) {
        if (n_comp > 4096u) {
            using TopkCubSort = cub::BlockRadixSort<uint64_t, 512, 16>;
            const int smem = (int)sizeof(typename TopkCubSort::TempStorage);
            int dev = 0;
            int max_optin_smem = 0;
            cudaError_t attr_err = cudaGetDevice(&dev);
            if (attr_err == cudaSuccess) {
                attr_err = cudaDeviceGetAttribute(&max_optin_smem,
                                                  cudaDevAttrMaxSharedMemoryPerBlockOptin,
                                                  dev);
            }
            if (attr_err == cudaSuccess && max_optin_smem >= smem) {
                attr_err = cudaFuncSetAttribute(indexer_topk_8192_cub_kernel,
                                                cudaFuncAttributeMaxDynamicSharedMemorySize,
                                                smem);
                if (attr_err == cudaSuccess) {
                    indexer_topk_8192_cub_kernel<<<n_tokens, 512, (size_t)smem>>>((uint32_t *)selected->ptr,
                                                                                 (const float *)scores->ptr,
                                                                                 n_comp, n_tokens, top_k);
                    return cuda_ok(cudaGetLastError(), "indexer topk 8192 cub launch");
                }
            }
        }
        indexer_topk_pow2_u16_kernel<8192><<<n_tokens, 1024>>>((uint32_t *)selected->ptr,
                                                               (const float *)scores->ptr,
                                                               n_comp, n_tokens, top_k);
        return cuda_ok(cudaGetLastError(), "indexer topk 8192 launch");
    }
    if (top_k == 512u && getenv("DS4_CUDA_NO_TOPK2048") == NULL &&
        getenv("DS4_CUDA_NO_TOPK_CHUNKED") == NULL) {
        const uint32_t chunk_n = 4096u;
        const uint32_t n_chunks = (n_comp + chunk_n - 1u) / chunk_n;
        const uint32_t candidate_stride = n_chunks * top_k;
        uint32_t n_sets = n_chunks;
        uint64_t scratch_u32_per_token = candidate_stride;
        while (n_sets > DS4_CUDA_TOPK_MERGE_GROUP) {
            n_sets = (n_sets + DS4_CUDA_TOPK_MERGE_GROUP - 1u) / DS4_CUDA_TOPK_MERGE_GROUP;
            scratch_u32_per_token += (uint64_t)n_sets * top_k;
        }
        if (scratch_u32_per_token > UINT64_MAX / n_tokens / sizeof(uint32_t)) return 0;
        const uint64_t tmp_bytes = (uint64_t)n_tokens * scratch_u32_per_token * sizeof(uint32_t);
        uint32_t *scratch = (uint32_t *)cuda_tmp_alloc(tmp_bytes, "indexer topk tree");
        if (!scratch) return 0;

        uint32_t *cur = scratch;
        n_sets = n_chunks;
        uint32_t cur_stride = candidate_stride;
        dim3 grid_chunks(n_tokens, n_chunks, 1);
        indexer_topk_chunk_pow2_kernel<4096><<<grid_chunks, 1024>>>(cur,
                                                                    (const float *)scores->ptr,
                                                                    n_comp,
                                                                    n_tokens,
                                                                    top_k,
                                                                    candidate_stride);
        if (!cuda_ok(cudaGetLastError(), "indexer topk chunk launch")) return 0;

        while (n_sets > DS4_CUDA_TOPK_MERGE_GROUP) {
            const uint32_t next_sets = (n_sets + DS4_CUDA_TOPK_MERGE_GROUP - 1u) / DS4_CUDA_TOPK_MERGE_GROUP;
            const uint32_t next_stride = next_sets * top_k;
            uint32_t *next = cur + (uint64_t)n_tokens * cur_stride;
            dim3 grid_merge(n_tokens, next_sets, 1);
            indexer_topk_tree_merge_pow2_kernel<4096><<<grid_merge, 1024>>>(
                    next,
                    cur,
                    (const float *)scores->ptr,
                    n_comp,
                    n_tokens,
                    top_k,
                    n_sets,
                    DS4_CUDA_TOPK_MERGE_GROUP,
                    cur_stride,
                    next_stride);
            if (!cuda_ok(cudaGetLastError(), "indexer topk tree merge launch")) return 0;
            cur = next;
            n_sets = next_sets;
            cur_stride = next_stride;
        }

        indexer_topk_merge_pow2_kernel<4096><<<n_tokens, 1024>>>((uint32_t *)selected->ptr,
                                                                 cur,
                                                                 (const float *)scores->ptr,
                                                                 n_comp,
                                                                 n_tokens,
                                                                 top_k,
                                                                 n_sets * top_k,
                                                                 cur_stride);
        return cuda_ok(cudaGetLastError(), "indexer topk tree final launch");
    }
    indexer_topk_kernel<<<n_tokens, 1>>>((uint32_t *)selected->ptr,
                                         (const float *)scores->ptr,
                                         n_comp, n_tokens, top_k);
    return cuda_ok(cudaGetLastError(), "indexer topk launch");
}

extern "C" int ds4_gpu_indexer_topk_presorted_tensor(
        ds4_gpu_tensor       *ranked,
        ds4_gpu_tensor       *ascending,
        const ds4_gpu_tensor *scores,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k) {
    const uint64_t output_bytes =
        (uint64_t)n_tokens * top_k * sizeof(uint32_t);
    if (!ranked || !ascending || !scores || n_comp == 0u || n_tokens == 0u ||
        top_k != 512u || top_k > n_comp || n_comp > 2048u ||
        ranked->ptr == ascending->ptr ||
        scores->bytes < (uint64_t)n_tokens * n_comp * sizeof(float) ||
        ranked->bytes < output_bytes || ascending->bytes < output_bytes) {
        return 0;
    }
    if (n_comp <= 1024u) {
        return indexer_topk_cub_exact_launch<1024u, 8u>(
                (uint32_t *)ranked->ptr,
                (uint32_t *)ascending->ptr,
                (const float *)scores->ptr,
                n_comp,
                n_tokens);
    }
    return indexer_topk_cub_exact_launch<2048u, 16u>(
            (uint32_t *)ranked->ptr,
            (uint32_t *)ascending->ptr,
            (const float *)scores->ptr,
            n_comp,
            n_tokens);
}

extern "C" int ds4_gpu_argmax_tensor(
        ds4_gpu_tensor       *out_idx,
        const ds4_gpu_tensor *logits,
        uint32_t                n_vocab) {
    if (!out_idx || !logits || n_vocab == 0 ||
        out_idx->bytes < sizeof(int32_t) ||
        logits->bytes < (uint64_t)n_vocab * sizeof(float)) {
        return 0;
    }
    argmax_kernel<<<1, 1024>>>((int32_t *)out_idx->ptr,
                               (const float *)logits->ptr,
                               n_vocab);
    return cuda_ok(cudaGetLastError(), "argmax launch");
}

extern "C" int ds4_gpu_dsv4_topk_mask_tensor(
        ds4_gpu_tensor       *mask,
        const ds4_gpu_tensor *topk,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k) {
    if (!mask || !topk || n_comp == 0 || n_tokens == 0 || top_k == 0 ||
        mask->bytes < (uint64_t)n_tokens * n_comp * sizeof(float) ||
        topk->bytes < (uint64_t)n_tokens * top_k * sizeof(uint32_t)) {
        return 0;
    }
    uint64_t n = (uint64_t)n_tokens * n_comp;
    uint64_t nk = (uint64_t)n_tokens * top_k;
    uint64_t blocks = ((n > nk ? n : nk) + 255) / 256;
    topk_mask_kernel<<<blocks, 256>>>((float *)mask->ptr,
                                      (const uint32_t *)topk->ptr,
                                      n_comp, n_tokens, top_k);
    return cuda_ok(cudaGetLastError(), "topk mask launch");
}
static int cuda_matmul_q8_0_tensor_labeled(ds4_gpu_tensor *out, const void *model_map, uint64_t model_size, uint64_t weight_offset, uint64_t in_dim, uint64_t out_dim, const ds4_gpu_tensor *x, uint64_t n_tok, const char *label) {
    if (!out || !x || !model_map) return 0;
    uint64_t blocks = (in_dim + 31) / 32;
    if (weight_offset > model_size || out_dim > UINT64_MAX / (blocks * 34)) return 0;
    uint64_t weight_bytes = out_dim * blocks * 34;
    if (weight_bytes > model_size - weight_offset) return 0;
    if (x->bytes < n_tok * in_dim * sizeof(float) ||
        out->bytes < n_tok * out_dim * sizeof(float)) return 0;
    const char *wptr = cuda_model_range_ptr(model_map, weight_offset, weight_bytes, "q8_0");
    if (!wptr) return 0;
    if (g_cublas_ready && n_tok > 1) {
        const float *w_f32 = cuda_q8_f32_ptr(model_map, weight_offset, weight_bytes, in_dim, out_dim, label);
        if (w_f32) {
            const float alpha = 1.0f;
            const float beta = 0.0f;
            cublasStatus_t st = cublasSgemm(g_cublas,
                                            CUBLAS_OP_T,
                                            CUBLAS_OP_N,
                                            (int)out_dim,
                                            (int)n_tok,
                                            (int)in_dim,
                                            &alpha,
                                            w_f32,
                                            (int)in_dim,
                                            (const float *)x->ptr,
                                            (int)in_dim,
                                            &beta,
                                            (float *)out->ptr,
                                            (int)out_dim);
            return cublas_ok(st, "q8 fp32 matmul");
        }
        const __half *w_f16 = cuda_q8_f16_ptr(model_map, weight_offset, weight_bytes, in_dim, out_dim, label);
        if (w_f16) {
            const uint64_t xh_count = n_tok * in_dim;
            __half *xh = (__half *)cuda_tmp_alloc(xh_count * sizeof(__half), "q8 f16 gemm activations");
            if (!xh) return 0;
            f32_to_f16_kernel<<<(xh_count + 255) / 256, 256>>>(xh, (const float *)x->ptr, xh_count);
            if (!cuda_ok(cudaGetLastError(), "q8 f16 activation convert launch")) return 0;
            const float alpha = 1.0f;
            const float beta = 0.0f;
            cublasStatus_t st = cublasGemmEx(g_cublas,
                                             CUBLAS_OP_T,
                                             CUBLAS_OP_N,
                                             (int)out_dim,
                                             (int)n_tok,
                                             (int)in_dim,
                                             &alpha,
                                             w_f16,
                                             CUDA_R_16F,
                                             (int)in_dim,
                                             xh,
                                             CUDA_R_16F,
                                             (int)in_dim,
                                             &beta,
                                             out->ptr,
                                             CUDA_R_32F,
                                             (int)out_dim,
                                             CUDA_R_32F,
                                             CUBLAS_GEMM_DEFAULT);
            if (st == CUBLAS_STATUS_SUCCESS) return 1;
            fprintf(stderr, "ds4: cuBLAS q8 f16 matmul failed: status %d\n", (int)st);
            cuda_q8_f16_cache_disable_after_failure("cuBLAS f16 matmul failure",
                                                    in_dim * out_dim * sizeof(__half));
            /* The F16 expansion cache is only an optimization.  If cuBLAS
             * rejects the cached path under memory pressure, retry the same
             * operation through the native Q8 kernels below. */
        }
        /* Residency cache missed (budget spent on other tensors).  For
         * prefill-sized batches the native Q8 kernels below run ~10x off
         * cuBLAS (nsys on a 4096-token chunk: those fallbacks were 60% of
         * the whole chunk).  Dequantize the weight into the shared scratch
         * buffer for just this call and take the tensor-core GEMM anyway:
         * one extra pass over the weight bytes, amortized over n_tok rows.
         * Decode (n_tok == 1) never reaches this branch. */
        if (getenv("DS4_CUDA_NO_Q8_TRANSIENT_GEMM") == NULL) {
            uint64_t transient_min = 64;
            const char *tmin_env = getenv("DS4_CUDA_Q8_TRANSIENT_MIN_TOKENS");
            if (tmin_env && tmin_env[0]) {
                char *endp = NULL;
                long v = strtol(tmin_env, &endp, 10);
                if (endp != tmin_env && v > 1) transient_min = (uint64_t)v;
            }
            uint64_t transient_cap = 512ull * 1048576ull;
            const char *tcap_env = getenv("DS4_CUDA_Q8_TRANSIENT_MAX_MB");
            if (tcap_env && tcap_env[0]) {
                char *endp = NULL;
                long v = strtol(tcap_env, &endp, 10);
                if (endp != tcap_env && v > 0) transient_cap = (uint64_t)v * 1048576ull;
            }
            const uint64_t w_count = in_dim * out_dim;
            const uint64_t w_f16_bytes = w_count * sizeof(__half);
            if (n_tok >= transient_min && w_f16_bytes <= transient_cap &&
                in_dim <= UINT64_MAX / out_dim / sizeof(__half)) {
                const uint64_t xh_count = n_tok * in_dim;
                const uint64_t xh_off = (w_f16_bytes + 255ull) & ~255ull;
                const uint64_t total_bytes = xh_off + xh_count * sizeof(__half);
                void *tmp = cuda_tmp_alloc(total_bytes, "q8 transient f16 gemm");
                if (tmp) {
                    __half *wt = (__half *)tmp;
                    __half *xh = (__half *)((char *)tmp + xh_off);
                    dequant_q8_0_to_f16_kernel<<<(w_count + 255) / 256, 256>>>(
                            wt, reinterpret_cast<const unsigned char *>(wptr),
                            in_dim, out_dim, blocks);
                    int okq = cuda_ok(cudaGetLastError(), "q8 transient dequant launch");
                    if (okq) {
                        f32_to_f16_kernel<<<(xh_count + 255) / 256, 256>>>(
                                xh, (const float *)x->ptr, xh_count);
                        okq = cuda_ok(cudaGetLastError(), "q8 transient activation convert launch");
                    }
                    if (okq) {
                        const float alpha = 1.0f;
                        const float beta = 0.0f;
                        cublasStatus_t st = cublasGemmEx(g_cublas,
                                                         CUBLAS_OP_T,
                                                         CUBLAS_OP_N,
                                                         (int)out_dim,
                                                         (int)n_tok,
                                                         (int)in_dim,
                                                         &alpha,
                                                         wt,
                                                         CUDA_R_16F,
                                                         (int)in_dim,
                                                         xh,
                                                         CUDA_R_16F,
                                                         (int)in_dim,
                                                         &beta,
                                                         out->ptr,
                                                         CUDA_R_32F,
                                                         (int)out_dim,
                                                         CUDA_R_32F,
                                                         CUBLAS_GEMM_DEFAULT);
                        if (st == CUBLAS_STATUS_SUCCESS) return 1;
                        fprintf(stderr, "ds4: cuBLAS q8 transient matmul failed: status %d\n", (int)st);
                    }
                    /* Fall through to the native Q8 kernels below. */
                }
            }
        }
    }
    const uint64_t xq_bytes = n_tok * blocks * 32u;
    const uint64_t scale_offset = (xq_bytes + 15u) & ~15ull;
    const uint64_t tmp_bytes = scale_offset + n_tok * blocks * sizeof(float);
    void *tmp = cuda_tmp_alloc(tmp_bytes, "q8_0 prequant");
    if (!tmp) return 0;
    int8_t *xq = (int8_t *)tmp;
    float *xscale = (float *)((char *)tmp + scale_offset);
    const int use_dp4a = cuda_q8_use_dp4a();
    dim3 qgrid((unsigned)blocks, (unsigned)n_tok, 1);
    quantize_q8_0_f32_kernel<<<qgrid, 32>>>(xq, xscale, (const float *)x->ptr, in_dim, blocks);
    if (!cuda_ok(cudaGetLastError(), "matmul_q8_0 quantize launch")) return 0;
    if (n_tok == 1) {
        matmul_q8_0_preq_warp8_kernel<<<((unsigned)out_dim + 7u) / 8u, 256>>>(
                (float *)out->ptr,
                reinterpret_cast<const unsigned char *>(wptr),
                xq,
                xscale,
                in_dim,
                out_dim,
                blocks,
                use_dp4a);
        return cuda_ok(cudaGetLastError(), "matmul_q8_0 warp launch");
    }
    if (getenv("DS4_CUDA_NO_Q8_BATCH_WARP") == NULL && blocks <= 32u) {
        dim3 bgrid(((unsigned)out_dim + 7u) / 8u, (unsigned)n_tok, 1);
        matmul_q8_0_preq_batch_warp8_kernel<<<bgrid, 256>>>(
                (float *)out->ptr,
                reinterpret_cast<const unsigned char *>(wptr),
                xq,
                xscale,
                in_dim,
                out_dim,
                n_tok,
                blocks,
                use_dp4a);
        return cuda_ok(cudaGetLastError(), "matmul_q8_0 batch warp launch");
    }
    dim3 grid((unsigned)out_dim, (unsigned)n_tok, 1);
    matmul_q8_0_preq_kernel<<<grid, 256>>>((float *)out->ptr,
                                           reinterpret_cast<const unsigned char *>(wptr),
                                           xq,
                                           xscale,
                                           in_dim, out_dim, n_tok, blocks,
                                           use_dp4a);
    return cuda_ok(cudaGetLastError(), "matmul_q8_0 launch");
}

/* Exact counterpart of cuda_matmul_q8_0_tensor_labeled for an activation that
 * has already undergone the reference path's FP32->F16 conversion.  It uses
 * the same cached/transient Q8->F16 weights and identical cuBLAS arguments, but
 * deliberately fails closed when an FP32 weight-cache path would have been
 * selected. */
static int cuda_matmul_q8_0_f16_input_labeled(
        ds4_gpu_tensor       *out,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              in_dim,
        uint64_t              out_dim,
        const ds4_gpu_tensor *x_h,
        uint64_t              n_tok,
        const char           *label) {
    if (!out || !x_h || !model_map || !g_cublas_ready || n_tok <= 1u ||
        n_tok > INT_MAX || in_dim == 0 || in_dim > INT_MAX ||
        out_dim == 0 || out_dim > INT_MAX ||
        in_dim > UINT64_MAX / out_dim ||
        n_tok > UINT64_MAX / in_dim ||
        n_tok > UINT64_MAX / out_dim) {
        return 0;
    }
    const uint64_t blocks = (in_dim + 31u) / 32u;
    if (weight_offset > model_size ||
        out_dim > UINT64_MAX / (blocks * 34ull)) {
        return 0;
    }
    const uint64_t weight_bytes = out_dim * blocks * 34ull;
    const uint64_t input_elems = n_tok * in_dim;
    const uint64_t output_elems = n_tok * out_dim;
    if (input_elems > UINT64_MAX / sizeof(__half) ||
        output_elems > UINT64_MAX / sizeof(float) ||
        weight_bytes > model_size - weight_offset ||
        x_h->bytes < input_elems * sizeof(__half) ||
        out->bytes < output_elems * sizeof(float)) {
        return 0;
    }
    /* A cached FP32 weight changes both the activation type and GEMM entry
     * point in the reference path.  Let the caller replay its FP32 fallback
     * rather than silently changing arithmetic. */
    if (cuda_q8_f32_cache_allowed(label, in_dim, out_dim)) return 0;

    const char *wptr = cuda_model_range_ptr(
        model_map, weight_offset, weight_bytes, "q8_0");
    if (!wptr) return 0;

    const float alpha = 1.0f;
    const float beta = 0.0f;
    const __half *w_f16 = cuda_q8_f16_ptr(
        model_map, weight_offset, weight_bytes, in_dim, out_dim, label);
    if (w_f16) {
        const cublasStatus_t st = cublasGemmEx(
            g_cublas,
            CUBLAS_OP_T,
            CUBLAS_OP_N,
            (int)out_dim,
            (int)n_tok,
            (int)in_dim,
            &alpha,
            w_f16,
            CUDA_R_16F,
            (int)in_dim,
            (const __half *)x_h->ptr,
            CUDA_R_16F,
            (int)in_dim,
            &beta,
            out->ptr,
            CUDA_R_32F,
            (int)out_dim,
            CUDA_R_32F,
            CUBLAS_GEMM_DEFAULT);
        if (st == CUBLAS_STATUS_SUCCESS) return 1;
        fprintf(stderr,
                "ds4: cuBLAS q8 f16-input matmul failed: status %d\n",
                (int)st);
        cuda_q8_f16_cache_disable_after_failure(
            "cuBLAS f16-input matmul failure",
            in_dim * out_dim * sizeof(__half));
    }

    if (getenv("DS4_CUDA_NO_Q8_TRANSIENT_GEMM") != NULL) return 0;
    uint64_t transient_min = 64u;
    const char *tmin_env = getenv("DS4_CUDA_Q8_TRANSIENT_MIN_TOKENS");
    if (tmin_env && tmin_env[0]) {
        char *endp = NULL;
        const long v = strtol(tmin_env, &endp, 10);
        if (endp != tmin_env && v > 1) transient_min = (uint64_t)v;
    }
    uint64_t transient_cap = 512ull * 1048576ull;
    const char *tcap_env = getenv("DS4_CUDA_Q8_TRANSIENT_MAX_MB");
    if (tcap_env && tcap_env[0]) {
        char *endp = NULL;
        const long v = strtol(tcap_env, &endp, 10);
        if (endp != tcap_env && v > 0) {
            transient_cap = (uint64_t)v * 1048576ull;
        }
    }
    const uint64_t w_count = in_dim * out_dim;
    if (w_count > UINT64_MAX / sizeof(__half)) return 0;
    const uint64_t w_f16_bytes = w_count * sizeof(__half);
    if (n_tok < transient_min || w_f16_bytes > transient_cap) return 0;

    __half *wt = (__half *)cuda_tmp_alloc(
        w_f16_bytes, "q8 transient f16-input gemm");
    if (!wt) return 0;
    dequant_q8_0_to_f16_kernel<<<(w_count + 255u) / 256u, 256>>>(
        wt,
        reinterpret_cast<const unsigned char *>(wptr),
        in_dim,
        out_dim,
        blocks);
    if (!cuda_ok(cudaGetLastError(),
                 "q8 transient f16-input dequant launch")) {
        return 0;
    }
    const cublasStatus_t st = cublasGemmEx(
        g_cublas,
        CUBLAS_OP_T,
        CUBLAS_OP_N,
        (int)out_dim,
        (int)n_tok,
        (int)in_dim,
        &alpha,
        wt,
        CUDA_R_16F,
        (int)in_dim,
        (const __half *)x_h->ptr,
        CUDA_R_16F,
        (int)in_dim,
        &beta,
        out->ptr,
        CUDA_R_32F,
        (int)out_dim,
        CUDA_R_32F,
        CUBLAS_GEMM_DEFAULT);
    if (st == CUBLAS_STATUS_SUCCESS) return 1;
    fprintf(stderr,
            "ds4: cuBLAS q8 transient f16-input matmul failed: status %d\n",
            (int)st);
    return 0;
}

extern "C" int ds4_gpu_matmul_q8_0_tensor(ds4_gpu_tensor *out, const void *model_map, uint64_t model_size, uint64_t weight_offset, uint64_t in_dim, uint64_t out_dim, const ds4_gpu_tensor *x, uint64_t n_tok) {
    return cuda_matmul_q8_0_tensor_labeled(out, model_map, model_size, weight_offset,
                                           in_dim, out_dim, x, n_tok, "q8_0");
}

extern "C" int ds4_gpu_matmul_q8_0_f16_input_tensor(
        ds4_gpu_tensor       *out,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              in_dim,
        uint64_t              out_dim,
        const ds4_gpu_tensor *x_h,
        uint64_t              n_tok) {
    return cuda_matmul_q8_0_f16_input_labeled(
        out, model_map, model_size, weight_offset,
        in_dim, out_dim, x_h, n_tok, "q8_0");
}

static int cuda_prepare_reused_q8_f16_weight(
        ds4_gpu_tensor *weight_f16,
        uint32_t        populate_weight,
        const void     *model_map,
        uint64_t        model_size,
        uint64_t        weight_offset,
        uint64_t        in_dim,
        uint64_t        out_dim,
        uint64_t        n_tok,
        const char     *label) {
    if (!weight_f16 || !weight_f16->ptr || !model_map || !g_cublas_ready ||
        populate_weight > 1u || n_tok <= 1u || n_tok > INT_MAX ||
        in_dim == 0u || in_dim > INT_MAX ||
        out_dim == 0u || out_dim > INT_MAX ||
        in_dim > UINT64_MAX / out_dim) {
        return 0;
    }

    const uint64_t blocks = (in_dim + 31u) / 32u;
    if (weight_offset > model_size ||
        out_dim > UINT64_MAX / (blocks * 34ull)) {
        return 0;
    }
    const uint64_t weight_bytes = out_dim * blocks * 34ull;
    const uint64_t weight_elems = in_dim * out_dim;
    if (weight_elems > UINT64_MAX / sizeof(__half) ||
        weight_bytes > model_size - weight_offset) {
        return 0;
    }
    const uint64_t weight_f16_bytes = weight_elems * sizeof(__half);
    if (weight_f16->bytes < weight_f16_bytes) return 0;

    /* The ordinary entry point checks an existing FP32 cache before deciding
     * whether the current environment still permits creating one.  Mirror
     * both halves of that decision so reuse cannot change arithmetic. */
    auto f32_cached = g_q8_f32_by_offset.find(weight_offset);
    if (f32_cached != g_q8_f32_by_offset.end()) {
        const cuda_q8_f32_range &r = g_q8_f32_ranges[f32_cached->second];
        if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
            r.in_dim == in_dim && r.out_dim == out_dim) {
            return 0;
        }
    }
    if (cuda_q8_f32_cache_allowed(label, in_dim, out_dim) ||
        getenv("DS4_CUDA_NO_Q8_TRANSIENT_GEMM") != NULL) {
        return 0;
    }

    uint64_t transient_min = 64u;
    const char *tmin_env = getenv("DS4_CUDA_Q8_TRANSIENT_MIN_TOKENS");
    if (tmin_env && tmin_env[0]) {
        char *endp = NULL;
        const long v = strtol(tmin_env, &endp, 10);
        if (endp != tmin_env && v > 1) transient_min = (uint64_t)v;
    }
    uint64_t transient_cap = 512ull * 1048576ull;
    const char *tcap_env = getenv("DS4_CUDA_Q8_TRANSIENT_MAX_MB");
    if (tcap_env && tcap_env[0]) {
        char *endp = NULL;
        const long v = strtol(tcap_env, &endp, 10);
        if (endp != tcap_env && v > 0) {
            transient_cap = (uint64_t)v * 1048576ull;
        }
    }
    if (n_tok < transient_min || weight_f16_bytes > transient_cap) return 0;
    if (!populate_weight) return 1;

    const char *wptr = cuda_model_range_ptr(
        model_map, weight_offset, weight_bytes, label ? label : "q8_0");
    if (!wptr) return 0;
    dequant_q8_0_to_f16_kernel<<<
        (weight_elems + 255u) / 256u, 256>>>(
            (__half *)weight_f16->ptr,
            reinterpret_cast<const unsigned char *>(wptr),
            in_dim,
            out_dim,
            blocks);
    return cuda_ok(cudaGetLastError(),
                   "q8 reused f16 weight dequant launch");
}

static int cuda_matmul_q8_0_reuse_f16_weight_f16_input_labeled(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *weight_f16,
        uint32_t              populate_weight,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              in_dim,
        uint64_t              out_dim,
        const ds4_gpu_tensor *x_h,
        uint64_t              n_tok,
        const char           *label) {
    if (!out || !x_h || !out->ptr || !x_h->ptr ||
        in_dim == 0u || out_dim == 0u || n_tok == 0u ||
        n_tok > UINT64_MAX / in_dim || n_tok > UINT64_MAX / out_dim) {
        return 0;
    }
    const uint64_t input_elems = n_tok * in_dim;
    const uint64_t output_elems = n_tok * out_dim;
    if (input_elems > UINT64_MAX / sizeof(__half) ||
        output_elems > UINT64_MAX / sizeof(float) ||
        x_h->bytes < input_elems * sizeof(__half) ||
        out->bytes < output_elems * sizeof(float) ||
        !cuda_prepare_reused_q8_f16_weight(
            weight_f16, populate_weight, model_map, model_size,
            weight_offset, in_dim, out_dim, n_tok, label)) {
        return 0;
    }

    const float alpha = 1.0f;
    const float beta = 0.0f;
    const cublasStatus_t st = cublasGemmEx(
        g_cublas,
        CUBLAS_OP_T,
        CUBLAS_OP_N,
        (int)out_dim,
        (int)n_tok,
        (int)in_dim,
        &alpha,
        weight_f16->ptr,
        CUDA_R_16F,
        (int)in_dim,
        x_h->ptr,
        CUDA_R_16F,
        (int)in_dim,
        &beta,
        out->ptr,
        CUDA_R_32F,
        (int)out_dim,
        CUDA_R_32F,
        CUBLAS_GEMM_DEFAULT);
    if (st == CUBLAS_STATUS_SUCCESS) return 1;
    fprintf(stderr,
            "ds4: cuBLAS q8 reused f16-weight/f16-input matmul failed: "
            "status %d\n",
            (int)st);
    return 0;
}

extern "C" int ds4_gpu_matmul_q8_0_reuse_f16_weight_f16_input_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *weight_f16,
        uint32_t              populate_weight,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              in_dim,
        uint64_t              out_dim,
        const ds4_gpu_tensor *x_h,
        uint64_t              n_tok) {
    return cuda_matmul_q8_0_reuse_f16_weight_f16_input_labeled(
        out, weight_f16, populate_weight, model_map, model_size,
        weight_offset, in_dim, out_dim, x_h, n_tok, "q8_0");
}

extern "C" int ds4_gpu_matmul_q8_0_reuse_f16_weight_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *weight_f16,
        uint32_t              populate_weight,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              in_dim,
        uint64_t              out_dim,
        const ds4_gpu_tensor *x,
        uint64_t              n_tok) {
    if (!out || !x || !out->ptr || !x->ptr ||
        in_dim == 0u || out_dim == 0u || n_tok == 0u ||
        n_tok > UINT64_MAX / in_dim || n_tok > UINT64_MAX / out_dim) {
        return 0;
    }
    const uint64_t input_elems = n_tok * in_dim;
    const uint64_t output_elems = n_tok * out_dim;
    if (input_elems > UINT64_MAX / sizeof(float) ||
        input_elems > UINT64_MAX / sizeof(__half) ||
        output_elems > UINT64_MAX / sizeof(float) ||
        x->bytes < input_elems * sizeof(float) ||
        out->bytes < output_elems * sizeof(float) ||
        !cuda_prepare_reused_q8_f16_weight(
            weight_f16, populate_weight, model_map, model_size,
            weight_offset, in_dim, out_dim, n_tok, "q8_0")) {
        return 0;
    }

    __half *xh = (__half *)cuda_tmp_alloc(
        input_elems * sizeof(__half), "q8 reused f16 gemm activations");
    if (!xh) return 0;
    f32_to_f16_kernel<<<(input_elems + 255u) / 256u, 256>>>(
        xh, (const float *)x->ptr, input_elems);
    if (!cuda_ok(cudaGetLastError(),
                 "q8 reused f16 activation convert launch")) {
        return 0;
    }

    const float alpha = 1.0f;
    const float beta = 0.0f;
    const cublasStatus_t st = cublasGemmEx(
        g_cublas,
        CUBLAS_OP_T,
        CUBLAS_OP_N,
        (int)out_dim,
        (int)n_tok,
        (int)in_dim,
        &alpha,
        weight_f16->ptr,
        CUDA_R_16F,
        (int)in_dim,
        xh,
        CUDA_R_16F,
        (int)in_dim,
        &beta,
        out->ptr,
        CUDA_R_32F,
        (int)out_dim,
        CUDA_R_32F,
        CUBLAS_GEMM_DEFAULT);
    if (st == CUBLAS_STATUS_SUCCESS) return 1;
    fprintf(stderr,
            "ds4: cuBLAS q8 reused f16-weight matmul failed: status %d\n",
            (int)st);
    return 0;
}

extern "C" int ds4_gpu_matmul_q8_0_pair_tensor(
        ds4_gpu_tensor *out0,
        ds4_gpu_tensor *out1,
        const void *model_map,
        uint64_t model_size,
        uint64_t weight0_offset,
        uint64_t weight1_offset,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim,
        const ds4_gpu_tensor *x,
        uint64_t n_tok) {
    if (!out0 || !out1 || !x || !model_map || in_dim == 0 || out0_dim == 0 || out1_dim == 0 || n_tok == 0) {
        return 0;
    }
    if (n_tok != 1) {
        return cuda_matmul_q8_0_tensor_labeled(out0, model_map, model_size, weight0_offset,
                                               in_dim, out0_dim, x, n_tok, "q8_0_pair0") &&
               cuda_matmul_q8_0_tensor_labeled(out1, model_map, model_size, weight1_offset,
                                               in_dim, out1_dim, x, n_tok, "q8_0_pair1");
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    if (weight0_offset > model_size || weight1_offset > model_size ||
        out0_dim > UINT64_MAX / (blocks * 34) ||
        out1_dim > UINT64_MAX / (blocks * 34)) {
        return 0;
    }
    const uint64_t weight0_bytes = out0_dim * blocks * 34;
    const uint64_t weight1_bytes = out1_dim * blocks * 34;
    if (weight0_bytes > model_size - weight0_offset ||
        weight1_bytes > model_size - weight1_offset ||
        x->bytes < in_dim * sizeof(float) ||
        out0->bytes < out0_dim * sizeof(float) ||
        out1->bytes < out1_dim * sizeof(float)) {
        return 0;
    }
    const char *w0 = cuda_model_range_ptr(model_map, weight0_offset, weight0_bytes, "q8_0_pair0");
    const char *w1 = cuda_model_range_ptr(model_map, weight1_offset, weight1_bytes, "q8_0_pair1");
    if (!w0 || !w1) return 0;

    const uint64_t xq_bytes = blocks * 32u;
    const uint64_t scale_offset = (xq_bytes + 15u) & ~15ull;
    const uint64_t tmp_bytes = scale_offset + blocks * sizeof(float);
    void *tmp = cuda_tmp_alloc(tmp_bytes, "q8_0 pair prequant");
    if (!tmp) return 0;
    int8_t *xq = (int8_t *)tmp;
    float *xscale = (float *)((char *)tmp + scale_offset);
    const int use_dp4a = cuda_q8_use_dp4a();
    dim3 qgrid((unsigned)blocks, 1, 1);
    quantize_q8_0_f32_kernel<<<qgrid, 32>>>(xq, xscale, (const float *)x->ptr, in_dim, blocks);
    if (!cuda_ok(cudaGetLastError(), "matmul_q8_0 pair quantize launch")) return 0;
    const uint64_t max_out = out0_dim > out1_dim ? out0_dim : out1_dim;
    matmul_q8_0_pair_preq_warp8_kernel<<<((unsigned)max_out + 7u) / 8u, 256>>>(
            (float *)out0->ptr,
            (float *)out1->ptr,
            reinterpret_cast<const unsigned char *>(w0),
            reinterpret_cast<const unsigned char *>(w1),
            xq,
            xscale,
            in_dim,
            out0_dim,
            out1_dim,
            blocks,
            use_dp4a);
    return cuda_ok(cudaGetLastError(), "matmul_q8_0 pair warp launch");
}

extern "C" int ds4_gpu_matmul_q8_0_f16_out_tensor(
        ds4_gpu_tensor *out_h,
        const void *model_map,
        uint64_t model_size,
        uint64_t weight_offset,
        uint64_t in_dim,
        uint64_t out_dim,
        const ds4_gpu_tensor *x,
        uint64_t n_tok) {
    (void)out_h; (void)model_map; (void)model_size; (void)weight_offset;
    (void)in_dim; (void)out_dim; (void)x; (void)n_tok;
    return 0;
}

static int cuda_matmul_q8_0_hc_expand_tensor_labeled(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *block_add,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc,
        const char             *label) {
    if (!out_hc || !block_out || !x || !residual_hc || !split || !model_map ||
        in_dim == 0 || out_dim == 0 || n_embd == 0 || n_hc == 0 ||
        out_dim != (uint64_t)n_embd) {
        return 0;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    if (weight_offset > model_size || out_dim > UINT64_MAX / (blocks * 34)) return 0;
    const uint64_t weight_bytes = out_dim * blocks * 34;
    const uint64_t hc_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t split_bytes = (uint64_t)(2u * n_hc + n_hc * n_hc) * sizeof(float);
    if (weight_bytes > model_size - weight_offset ||
        x->bytes < in_dim * sizeof(float) ||
        block_out->bytes < out_dim * sizeof(float) ||
        residual_hc->bytes < hc_bytes ||
        split->bytes < split_bytes ||
        out_hc->bytes < hc_bytes ||
        (block_add && block_add->bytes < out_dim * sizeof(float))) {
        return 0;
    }
    const char *wptr = cuda_model_range_ptr(model_map, weight_offset, weight_bytes, label ? label : "q8_0_hc_expand");
    if (!wptr) return 0;

    const uint64_t xq_bytes = blocks * 32u;
    const uint64_t scale_offset = (xq_bytes + 15u) & ~15ull;
    const uint64_t tmp_bytes = scale_offset + blocks * sizeof(float);
    void *tmp = cuda_tmp_alloc(tmp_bytes, "q8_0 hc expand prequant");
    if (!tmp) return 0;
    int8_t *xq = (int8_t *)tmp;
    float *xscale = (float *)((char *)tmp + scale_offset);
    const int use_dp4a = cuda_q8_use_dp4a();
    quantize_q8_0_f32_kernel<<<(unsigned)blocks, 32>>>(xq, xscale, (const float *)x->ptr, in_dim, blocks);
    if (!cuda_ok(cudaGetLastError(), "matmul_q8_0_hc_expand quantize launch")) return 0;
    matmul_q8_0_hc_expand_preq_warp8_kernel<<<((unsigned)out_dim + 7u) / 8u, 256>>>(
            (float *)out_hc->ptr,
            (float *)block_out->ptr,
            block_add ? (const float *)block_add->ptr : (const float *)block_out->ptr,
            (const float *)residual_hc->ptr,
            (const float *)split->ptr,
            reinterpret_cast<const unsigned char *>(wptr),
            xq,
            xscale,
            in_dim,
            out_dim,
            n_embd,
            n_hc,
            blocks,
            block_add ? 1 : 0,
            use_dp4a);
    return cuda_ok(cudaGetLastError(), "matmul_q8_0_hc_expand launch");
}

extern "C" int ds4_gpu_matmul_f16_tensor(ds4_gpu_tensor *out, const void *model_map, uint64_t model_size, uint64_t weight_offset, uint64_t in_dim, uint64_t out_dim, const ds4_gpu_tensor *x, uint64_t n_tok) {
    if (!out || !x || !model_map) return 0;
    if (weight_offset > model_size || out_dim > UINT64_MAX / in_dim) return 0;
    uint64_t weight_bytes = out_dim * in_dim * sizeof(uint16_t);
    if (weight_bytes > model_size - weight_offset) return 0;
    if (x->bytes < n_tok * in_dim * sizeof(float) ||
        out->bytes < n_tok * out_dim * sizeof(float)) return 0;
    const char *wptr = cuda_model_range_ptr(model_map, weight_offset, weight_bytes, "f16");
    if (!wptr) return 0;
    const __half *w = (const __half *)wptr;
    const int serial_f16 = getenv("DS4_CUDA_SERIAL_F16_MATMUL") != NULL;
    const int router_shape = in_dim == 4096u && out_dim == 256u && n_tok == 1u;
    const int serial_router =
        !serial_f16 &&
        router_shape &&
        getenv("DS4_CUDA_SERIAL_ROUTER") != NULL;
    const int ordered_router =
        !serial_f16 &&
        !serial_router &&
        n_tok == 1u &&
        getenv("DS4_CUDA_NO_ORDERED_F16_MATMUL") == NULL;
    if (!serial_f16 && g_cublas_ready && n_tok > 1) {
        const uint64_t xh_count = n_tok * in_dim;
        __half *xh = (__half *)cuda_tmp_alloc(xh_count * sizeof(__half), "f16 gemm activations");
        if (!xh) return 0;
        f32_to_f16_kernel<<<(xh_count + 255) / 256, 256>>>(xh, (const float *)x->ptr, xh_count);
        if (!cuda_ok(cudaGetLastError(), "f16 activation convert launch")) return 0;
        const float alpha = 1.0f;
        const float beta = 0.0f;
        cublasStatus_t st = cublasGemmEx(g_cublas,
                                         CUBLAS_OP_T,
                                         CUBLAS_OP_N,
                                         (int)out_dim,
                                         (int)n_tok,
                                         (int)in_dim,
                                         &alpha,
                                         w,
                                         CUDA_R_16F,
                                         (int)in_dim,
                                         xh,
                                         CUDA_R_16F,
                                         (int)in_dim,
                                         &beta,
                                         out->ptr,
                                         CUDA_R_32F,
                                         (int)out_dim,
                                         CUDA_R_32F,
                                         CUBLAS_GEMM_DEFAULT);
        return cublas_ok(st, "f16 matmul");
    }
    dim3 grid((unsigned)out_dim, (unsigned)n_tok, 1);
    if (serial_f16 || serial_router) {
        matmul_f16_serial_kernel<<<grid, 1>>>((float *)out->ptr, w, (const float *)x->ptr, in_dim, out_dim, n_tok);
        return cuda_ok(cudaGetLastError(), serial_router ? "matmul_f16_router_serial launch" : "matmul_f16_serial launch");
    }
    if (ordered_router) {
        if (getenv("DS4_CUDA_F16_COALESCED_GEMV") != NULL) {
            matmul_f16_coalesced_gemv_kernel<<<grid, 32>>>((float *)out->ptr, w, (const float *)x->ptr, in_dim, out_dim, n_tok);
            return cuda_ok(cudaGetLastError(), "matmul_f16_coalesced_gemv launch");
        }
        matmul_f16_ordered_chunks_kernel<<<grid, 32>>>((float *)out->ptr, w, (const float *)x->ptr, in_dim, out_dim, n_tok);
        return cuda_ok(cudaGetLastError(), "matmul_f16_ordered_chunks launch");
    }
    matmul_f16_kernel<<<grid, 256>>>((float *)out->ptr, w, (const float *)x->ptr, in_dim, out_dim, n_tok);
    return cuda_ok(cudaGetLastError(), "matmul_f16 launch");
}

extern "C" int ds4_gpu_matmul_f16_input_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x_h,
        uint32_t                rows) {
    if (!out || !x_h || !model_map || !g_cublas_ready ||
        getenv("DS4_CUDA_SERIAL_F16_MATMUL") != NULL ||
        rows <= 1u || rows > INT_MAX ||
        in_dim == 0 || in_dim > INT_MAX || out_dim == 0 || out_dim > INT_MAX ||
        in_dim > UINT64_MAX / out_dim ||
        (uint64_t)rows > UINT64_MAX / in_dim ||
        (uint64_t)rows > UINT64_MAX / out_dim) {
        return 0;
    }
    const uint64_t weight_elems = in_dim * out_dim;
    const uint64_t input_elems = (uint64_t)rows * in_dim;
    const uint64_t output_elems = (uint64_t)rows * out_dim;
    if (weight_elems > UINT64_MAX / sizeof(__half) ||
        input_elems > UINT64_MAX / sizeof(__half) ||
        output_elems > UINT64_MAX / sizeof(float)) {
        return 0;
    }
    const uint64_t weight_bytes = weight_elems * sizeof(__half);
    if (weight_offset > model_size || weight_bytes > model_size - weight_offset ||
        x_h->bytes < input_elems * sizeof(__half) ||
        out->bytes < output_elems * sizeof(float)) {
        return 0;
    }
    const char *wptr = cuda_model_range_ptr(
            model_map, weight_offset, weight_bytes, "f16 input matmul");
    if (!wptr) return 0;

    const float alpha = 1.0f;
    const float beta = 0.0f;
    const cublasStatus_t st = cublasGemmEx(g_cublas,
                                           CUBLAS_OP_T,
                                           CUBLAS_OP_N,
                                           (int)out_dim,
                                           (int)rows,
                                           (int)in_dim,
                                           &alpha,
                                           (const __half *)wptr,
                                           CUDA_R_16F,
                                           (int)in_dim,
                                           (const __half *)x_h->ptr,
                                           CUDA_R_16F,
                                           (int)in_dim,
                                           &beta,
                                           out->ptr,
                                           CUDA_R_32F,
                                           (int)out_dim,
                                           CUDA_R_32F,
                                           CUBLAS_GEMM_DEFAULT);
    return cublas_ok(st, "f16 input matmul");
}

extern "C" int ds4_gpu_rms_norm_plain_f16_matmul_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_h,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint32_t                rows,
        float                   eps) {
    if (!out || !norm_h || !x || !model_map || !g_cublas_ready || rows <= 1u ||
        in_dim == 0 || in_dim > UINT32_MAX || out_dim == 0 ||
        out_dim > UINT64_MAX / in_dim ||
        (uint64_t)rows > UINT64_MAX / in_dim) {
        return 0;
    }
    const uint64_t weight_elems = in_dim * out_dim;
    if (weight_elems > UINT64_MAX / sizeof(__half)) return 0;
    const uint64_t weight_bytes = weight_elems * sizeof(__half);
    const uint64_t input_elems = (uint64_t)rows * in_dim;
    if (input_elems > UINT64_MAX / sizeof(float) ||
        (uint64_t)rows > UINT64_MAX / out_dim / sizeof(float) ||
        weight_offset > model_size || weight_bytes > model_size - weight_offset ||
        x->bytes < input_elems * sizeof(float) ||
        norm_h->bytes < input_elems * sizeof(__half) ||
        out->bytes < (uint64_t)rows * out_dim * sizeof(float)) {
        return 0;
    }
    const char *wptr = cuda_model_range_ptr(
            model_map, weight_offset, weight_bytes, "rms_norm_f16_matmul");
    if (!wptr) return 0;

    rms_norm_plain_f16_kernel<<<rows, 256>>>((__half *)norm_h->ptr,
                                             (const float *)x->ptr,
                                             (uint32_t)in_dim,
                                             rows,
                                             eps);
    if (!cuda_ok(cudaGetLastError(), "rms norm f16 launch")) return 0;

    const float alpha = 1.0f;
    const float beta = 0.0f;
    const cublasStatus_t st = cublasGemmEx(g_cublas,
                                           CUBLAS_OP_T,
                                           CUBLAS_OP_N,
                                           (int)out_dim,
                                           (int)rows,
                                           (int)in_dim,
                                           &alpha,
                                           (const __half *)wptr,
                                           CUDA_R_16F,
                                           (int)in_dim,
                                           (const __half *)norm_h->ptr,
                                           CUDA_R_16F,
                                           (int)in_dim,
                                           &beta,
                                           out->ptr,
                                           CUDA_R_32F,
                                           (int)out_dim,
                                           CUDA_R_32F,
                                           CUBLAS_GEMM_DEFAULT);
    return cublas_ok(st, "rms norm f16 matmul");
}

extern "C" int ds4_gpu_matmul_f16_pair_tensor(
        ds4_gpu_tensor *out0,
        ds4_gpu_tensor *out1,
        const void *model_map,
        uint64_t model_size,
        uint64_t weight0_offset,
        uint64_t weight1_offset,
        uint64_t in_dim,
        uint64_t out_dim,
        const ds4_gpu_tensor *x,
        uint64_t n_tok) {
    if (!out0 || !out1 || !x || !model_map || in_dim == 0 || out_dim == 0 || n_tok == 0) {
        return 0;
    }
    if (n_tok != 1 ||
        getenv("DS4_CUDA_NO_F16_PAIR_MATMUL") != NULL ||
        getenv("DS4_CUDA_SERIAL_F16_MATMUL") != NULL ||
        getenv("DS4_CUDA_SERIAL_ROUTER") != NULL ||
        getenv("DS4_CUDA_NO_ORDERED_F16_MATMUL") != NULL) {
        return ds4_gpu_matmul_f16_tensor(out0, model_map, model_size, weight0_offset,
                                           in_dim, out_dim, x, n_tok) &&
               ds4_gpu_matmul_f16_tensor(out1, model_map, model_size, weight1_offset,
                                           in_dim, out_dim, x, n_tok);
    }
    if (weight0_offset > model_size || weight1_offset > model_size ||
        out_dim > UINT64_MAX / in_dim) {
        return 0;
    }
    const uint64_t weight_bytes = out_dim * in_dim * sizeof(uint16_t);
    if (weight_bytes > model_size - weight0_offset ||
        weight_bytes > model_size - weight1_offset ||
        x->bytes < in_dim * sizeof(float) ||
        out0->bytes < out_dim * sizeof(float) ||
        out1->bytes < out_dim * sizeof(float)) {
        return 0;
    }
    const __half *w0 = (const __half *)cuda_model_range_ptr(model_map, weight0_offset, weight_bytes, "f16_pair0");
    const __half *w1 = (const __half *)cuda_model_range_ptr(model_map, weight1_offset, weight_bytes, "f16_pair1");
    if (!w0 || !w1) return 0;
    if (getenv("DS4_CUDA_F16_COALESCED_GEMV") != NULL) {
        matmul_f16_coalesced_pair_gemv_kernel<<<(unsigned)out_dim, 32>>>(
            (float *)out0->ptr, (float *)out1->ptr, w0, w1,
            (const float *)x->ptr, in_dim, out_dim, out_dim);
        return cuda_ok(cudaGetLastError(), "matmul_f16_coalesced_pair_gemv launch");
    }
    matmul_f16_pair_ordered_chunks_kernel<<<(unsigned)out_dim, 32>>>(
        (float *)out0->ptr,
        (float *)out1->ptr,
        w0,
        w1,
        (const float *)x->ptr,
        in_dim,
        out_dim,
        out_dim);
    return cuda_ok(cudaGetLastError(), "matmul_f16_pair_ordered_chunks launch");
}

extern "C" int ds4_gpu_matmul_f32_tensor(ds4_gpu_tensor *out, const void *model_map, uint64_t model_size, uint64_t weight_offset, uint64_t in_dim, uint64_t out_dim, const ds4_gpu_tensor *x, uint64_t n_tok) {
    if (!out || !x || !model_map || in_dim == 0 || out_dim == 0 || n_tok == 0) return 0;
    if (weight_offset > model_size || out_dim > UINT64_MAX / in_dim) return 0;
    uint64_t weight_elems = out_dim * in_dim;
    if (weight_elems > UINT64_MAX / sizeof(float)) return 0;
    uint64_t weight_bytes = weight_elems * sizeof(float);
    if (weight_bytes > model_size - weight_offset) return 0;
    if (x->bytes < n_tok * in_dim * sizeof(float) ||
        out->bytes < n_tok * out_dim * sizeof(float)) return 0;
    const char *wptr = cuda_model_range_ptr(model_map, weight_offset, weight_bytes, "f32");
    if (!wptr) return 0;
    const float *w = (const float *)wptr;
    if (g_cublas_ready && n_tok > 1) {
        const float alpha = 1.0f;
        const float beta = 0.0f;
        cublasStatus_t st = cublasSgemm(g_cublas,
                                        CUBLAS_OP_T,
                                        CUBLAS_OP_N,
                                        (int)out_dim,
                                        (int)n_tok,
                                        (int)in_dim,
                                        &alpha,
                                        w,
                                        (int)in_dim,
                                        (const float *)x->ptr,
                                        (int)in_dim,
                                        &beta,
                                        (float *)out->ptr,
                                        (int)out_dim);
        return cublas_ok(st, "f32 matmul");
    }
    dim3 grid((unsigned)out_dim, (unsigned)n_tok, 1);
    matmul_f32_kernel<<<grid, 256>>>((float *)out->ptr, w, (const float *)x->ptr, in_dim, out_dim, n_tok);
    return cuda_ok(cudaGetLastError(), "matmul_f32 launch");
}

extern "C" int ds4_gpu_repeat_hc_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *row, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !row || n_embd == 0 || n_hc == 0 ||
        row->bytes < (uint64_t)n_embd * sizeof(float) ||
        out->bytes < (uint64_t)n_embd * n_hc * sizeof(float)) {
        return 0;
