                uint64_t gate_x_bytes = 0u;
                uint64_t down_x_bytes = 0u;
                uint64_t gate_weight_bytes = 0u;
                uint64_t down_weight_bytes = 0u;
                uint64_t down_sorted_bytes = 0u;
                uint64_t inverse_sorted_bytes = 0u;
