                        moe_gate_up_mid_decode_lut_qwarp32_kernel<128u, true>
                            <<<qgrid, 256>>>(
                                (float *)gate->ptr, (float *)up->ptr,
                                (float *)mid->ptr, gate_w, up_w, xq,
                                selected_ptr, (const float *)weights->ptr,
