extern "C" int ds4_gpu_hc_split_sinkhorn_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *mix, const void *model_map, uint64_t model_size, uint64_t scale_offset, uint64_t base_offset, uint32_t n_hc, uint32_t sinkhorn_iters, float eps) {
    if (!out || !mix || !model_map || n_hc != 4) return 0;
    const uint64_t mix_bytes = 24ull * sizeof(float);
    if (scale_offset > model_size || model_size - scale_offset < 3ull * sizeof(float) ||
        base_offset > model_size || model_size - base_offset < mix_bytes ||
        mix->bytes < mix_bytes || out->bytes < mix_bytes) return 0;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    uint32_t n_rows = (uint32_t)(mix->bytes / mix_bytes);
    if (out->bytes / mix_bytes < n_rows) n_rows = (uint32_t)(out->bytes / mix_bytes);
    hc_split_sinkhorn_kernel<<<(n_rows + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)mix->ptr,
        scale,
        base,
        n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc_split_sinkhorn launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *weights, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)weights->ptr,
        n_embd, n_hc, n_tokens, n_hc);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_split_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    uint32_t stride = (uint32_t)(2u * n_hc + n_hc * n_hc);
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)split->ptr,
        n_embd, n_hc, n_tokens, stride);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum_split launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc != 4) {
        return 0;
    }
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
        scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || mix_bytes > model_size - base_offset) {
        return 0;
    }
    uint64_t n_rows = out->bytes / out_row_bytes;
    if (mix->bytes < n_rows * mix_bytes ||
        split->bytes < n_rows * mix_bytes ||
        residual_hc->bytes < n_rows * residual_row_bytes) {
        return 0;
    }
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    hc_split_weighted_sum_fused_kernel<<<(uint32_t)n_rows, 256>>>(
            (float *)out->ptr,
            (float *)split->ptr,
            (const float *)mix->ptr,
            (const float *)residual_hc->ptr,
            scale,
            base,
            n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc split weighted sum launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps) {
    if (getenv("DS4_CUDA_DISABLE_HC_SPLIT_NORM_FUSED") == NULL) {
        if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
            n_embd == 0 || n_hc != 4) {
            return 0;
        }
        const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
        const uint64_t mix_bytes = mix_hc * sizeof(float);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
        if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
            norm_out->bytes < out->bytes ||
            scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            (uint64_t)n_embd * sizeof(float) > model_size - norm_weight_offset) {
            return 0;
        }
        uint64_t n_rows = out->bytes / out_row_bytes;
        if (n_rows == 1) {
            if (mix->bytes < n_rows * mix_bytes ||
                split->bytes < n_rows * mix_bytes ||
                residual_hc->bytes < n_rows * residual_row_bytes) {
                return 0;
            }
            const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset,
                    3ull * sizeof(float), "hc_scale");
            const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset,
                    mix_bytes, "hc_base");
            const float *norm_w = (const float *)cuda_model_range_ptr(model_map, norm_weight_offset,
                    (uint64_t)n_embd * sizeof(float), "hc_norm_weight");
            if (!scale || !base || !norm_w) return 0;
            hc_split_weighted_sum_norm_fused_kernel<<<(uint32_t)n_rows, 256>>>(
                    (float *)out->ptr,
                    (float *)norm_out->ptr,
                    (float *)split->ptr,
                    (const float *)mix->ptr,
                    (const float *)residual_hc->ptr,
                    scale,
                    base,
                    norm_w,
                    n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps, norm_eps);
            return cuda_ok(cudaGetLastError(), "hc split weighted sum norm launch");
        }
    }
    return ds4_gpu_hc_split_weighted_sum_tensor(out, split, mix, residual_hc,
                                                  model_map, model_size,
                                                  scale_offset, base_offset,
                                                  n_embd, n_hc,
                                                  sinkhorn_iters, eps) &&
           ds4_gpu_rms_norm_weight_tensor(norm_out, out, model_map, model_size,
                                            norm_weight_offset, n_embd, norm_eps);
}

extern "C" int ds4_gpu_hc_split_weighted_sum_norm_f16_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *norm_h,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              scale_offset,
        uint64_t              base_offset,
        uint64_t              norm_weight_offset,
        uint32_t              n_embd,
        uint32_t              n_hc,
        uint32_t              sinkhorn_iters,
        float                 eps,
        float                 norm_eps) {
    constexpr uint32_t fixed_n_embd = 4096u;
    constexpr uint32_t fixed_n_hc = 4u;
    constexpr uint64_t mix_hc = 24u;
    if (!norm_out || !norm_h || !split || !mix || !residual_hc ||
        !model_map || n_embd != fixed_n_embd || n_hc != fixed_n_hc ||
        scale_offset > model_size || base_offset > model_size ||
        norm_weight_offset > model_size) {
        return 0;
    }

    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes =
        (uint64_t)fixed_n_embd * sizeof(float);
    const uint64_t norm_h_row_bytes =
        (uint64_t)fixed_n_embd * sizeof(__half);
    const uint64_t residual_row_bytes =
        (uint64_t)fixed_n_hc * fixed_n_embd * sizeof(float);
    const uint64_t norm_weight_bytes =
        (uint64_t)fixed_n_embd * sizeof(float);
    /* norm_out is graph-capacity scratch and may be larger than the active
     * chunk.  norm_h is always the exact active-row view, including when the
     * dead weighted F32 output is omitted.  Derive the launch shape from that
     * view so an 8192-capable graph can safely run 4096-row and partial tails. */
    if (norm_h->bytes < norm_h_row_bytes ||
        norm_h->bytes % norm_h_row_bytes != 0u ||
        model_size - scale_offset < 3u * sizeof(float) ||
        model_size - base_offset < mix_bytes ||
        model_size - norm_weight_offset < norm_weight_bytes) {
        return 0;
    }

    const uint64_t n_rows = norm_h->bytes / norm_h_row_bytes;
    if (n_rows <= 1u || n_rows > UINT32_MAX ||
        n_rows > UINT64_MAX / mix_bytes ||
        n_rows > UINT64_MAX / residual_row_bytes ||
        n_rows > UINT64_MAX / norm_h_row_bytes ||
        (out && out->bytes < n_rows * out_row_bytes) ||
        norm_out->bytes < n_rows * out_row_bytes ||
        norm_h->bytes < n_rows * norm_h_row_bytes ||
        mix->bytes < n_rows * mix_bytes ||
        split->bytes < n_rows * mix_bytes ||
        residual_hc->bytes < n_rows * residual_row_bytes) {
        return 0;
    }

    const float *scale = (const float *)cuda_model_range_ptr(
        model_map, scale_offset, 3u * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(
        model_map, base_offset, mix_bytes, "hc_base");
    const float *norm_w = (const float *)cuda_model_range_ptr(
        model_map, norm_weight_offset, norm_weight_bytes, "hc_norm_weight");
    if (!scale || !base || !norm_w) return 0;

    const int shared_false_timing =
        getenv("DS4_CUDA_HC_SHARED_INTERMEDIATE_FALSE_TIMING") != NULL;
    const int shared_only = out == NULL;
    if (shared_false_timing && !out) return 0;
    if (shared_false_timing || shared_only) {
        hc_split_weighted_sum_norm_f16_shared_kernel<<<
            (uint32_t)n_rows, 256>>>(
                (float *)norm_out->ptr,
                (__half *)norm_h->ptr,
                (float *)split->ptr,
                (const float *)mix->ptr,
                (const float *)residual_hc->ptr,
                scale,
                base,
                norm_w,
                n_embd,
                n_hc,
                (uint32_t)n_rows,
                sinkhorn_iters,
                eps,
                norm_eps);
        if (!cuda_ok(cudaGetLastError(),
                     "hc shared intermediate launch")) {
            return 0;
        }
        /* A NULL output is an explicit graph-level statement that the
         * weighted row has no consumer.  False timing instead supplies an
         * output and falls through to the stable, observable overwrite. */
        if (shared_only) return 1;
    }

    hc_split_weighted_sum_norm_f16_fused_kernel<<<
        (uint32_t)n_rows, 256>>>(
            (float *)out->ptr,
            (float *)norm_out->ptr,
            (__half *)norm_h->ptr,
            (float *)split->ptr,
            (const float *)mix->ptr,
            (const float *)residual_hc->ptr,
            scale,
            base,
            norm_w,
            n_embd,
            n_hc,
            (uint32_t)n_rows,
            sinkhorn_iters,
            eps,
            norm_eps);
    return cuda_ok(cudaGetLastError(),
                   "hc split weighted sum norm f16 launch");
}
extern "C" int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!out || !pre || !model_map || n_hc == 0) return 0;
    const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
    if (row_bytes == 0 || out->bytes < row_bytes || out->bytes % row_bytes != 0 ||
        pre->bytes < out->bytes ||
        scale_offset > model_size || sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || row_bytes > model_size - base_offset) {
        return 0;
    }
    const uint64_t n_tokens = out->bytes / row_bytes;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, sizeof(float), "output_hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, row_bytes, "output_hc_base");
    if (!scale || !base) return 0;
    uint64_t n = n_tokens * n_hc;
    output_hc_weights_kernel<<<(n + 255) / 256, 256>>>(
            (float *)out->ptr,
            (const float *)pre->ptr,
            scale,
            base,
            n_hc,
            (uint32_t)n_tokens,
            eps);
    return cuda_ok(cudaGetLastError(), "output hc weights launch");
}
extern "C" int ds4_gpu_hc_expand_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *post, const ds4_gpu_tensor *comb, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !post || !comb || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    (const float *)post->ptr,
                                                    (const float *)comb->ptr,
                                                    n_embd, n_hc, n_tokens,
                                                    n_hc, n_hc * n_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand launch");
}
extern "C" int ds4_gpu_hc_expand_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand_split launch");
}

static int cuda_hc_expand_split_rms_f16_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *norm_h,
        const ds4_gpu_tensor *block_out,
        const ds4_gpu_tensor *block_add,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc,
        float                   eps) {
    constexpr uint64_t fixed_n_embd = 4096u;
    constexpr uint64_t fixed_n_hc = 4u;
    constexpr uint64_t mix_hc = 24u;
    constexpr uint64_t hc_row_elems = fixed_n_hc * fixed_n_embd;
    constexpr uint64_t hc_row_bytes = hc_row_elems * sizeof(float);
    if (!out_hc || !norm_h || !block_out || !residual_hc || !split ||
        n_embd != fixed_n_embd || n_hc != fixed_n_hc ||
        out_hc->bytes == 0 || out_hc->bytes % hc_row_bytes != 0) {
        return 0;
    }
    const uint64_t n_tokens_u64 = out_hc->bytes / hc_row_bytes;
    if (n_tokens_u64 == 0 || n_tokens_u64 > UINT32_MAX) return 0;
    const uint64_t n_tokens = n_tokens_u64;
    if (n_tokens > UINT64_MAX / fixed_n_embd ||
        n_tokens > UINT64_MAX / mix_hc ||
        n_tokens > UINT64_MAX / hc_row_elems) {
        return 0;
    }
    const uint64_t block_elems = n_tokens * fixed_n_embd;
    const uint64_t split_elems = n_tokens * mix_hc;
    const uint64_t hc_elems = n_tokens * hc_row_elems;
    if (block_out->bytes < block_elems * sizeof(float) ||
        (block_add && block_add->bytes < block_elems * sizeof(float)) ||
        residual_hc->bytes < hc_elems * sizeof(float) ||
        split->bytes < split_elems * sizeof(float) ||
        norm_h->bytes < hc_elems * sizeof(__half)) {
        return 0;
    }

    if (block_add) {
        hc_expand_split_rms_f16_kernel<true><<<(uint32_t)n_tokens, 256>>>(
                (float *)out_hc->ptr,
                (__half *)norm_h->ptr,
                (const float *)block_out->ptr,
                (const float *)block_add->ptr,
                (const float *)residual_hc->ptr,
                (const float *)split->ptr,
                (uint32_t)n_tokens,
                eps);
        return cuda_ok(cudaGetLastError(), "hc expand add split rms f16 launch");
    }
    hc_expand_split_rms_f16_kernel<false><<<(uint32_t)n_tokens, 256>>>(
            (float *)out_hc->ptr,
            (__half *)norm_h->ptr,
            (const float *)block_out->ptr,
            (const float *)block_out->ptr,
            (const float *)residual_hc->ptr,
            (const float *)split->ptr,
            (uint32_t)n_tokens,
            eps);
    return cuda_ok(cudaGetLastError(), "hc expand split rms f16 launch");
}

extern "C" int ds4_gpu_hc_expand_split_rms_f16_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *norm_h,
        const ds4_gpu_tensor *block_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc,
        float                   eps) {
    return cuda_hc_expand_split_rms_f16_tensor(out_hc, norm_h, block_out, NULL,
                                                residual_hc, split,
                                                n_embd, n_hc, eps);
}

extern "C" int ds4_gpu_hc_expand_add_split_rms_f16_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *norm_h,
        const ds4_gpu_tensor *block_out,
        const ds4_gpu_tensor *block_add,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc,
        float                   eps) {
    if (!block_add) return 0;
    return cuda_hc_expand_split_rms_f16_tensor(out_hc, norm_h, block_out,
                                                block_add, residual_hc, split,
                                                n_embd, n_hc, eps);
}

extern "C" int ds4_gpu_hc_expand_routed_sum_add_split_rms_f16_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *norm_h,
        ds4_gpu_tensor       *routed_out,
        const ds4_gpu_tensor *routed_down,
        const ds4_gpu_tensor *shared_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                n_expert,
        float                   eps) {
    constexpr uint64_t fixed_n_embd = 4096u;
    constexpr uint64_t fixed_n_hc = 4u;
    constexpr uint64_t fixed_n_expert = 6u;
    constexpr uint64_t mix_hc = 24u;
    constexpr uint64_t hc_row_elems = fixed_n_hc * fixed_n_embd;
    constexpr uint64_t hc_row_bytes = hc_row_elems * sizeof(float);
    if (!out_hc || !norm_h || !routed_out || !routed_down || !shared_out ||
        !residual_hc || !split || !out_hc->ptr || !norm_h->ptr ||
        !routed_out->ptr || !routed_down->ptr || !shared_out->ptr ||
        !residual_hc->ptr || !split->ptr || n_embd != fixed_n_embd ||
        n_hc != fixed_n_hc || n_expert != fixed_n_expert ||
        out_hc->bytes == 0 || out_hc->bytes % hc_row_bytes != 0) {
        return 0;
    }
    const uint64_t n_tokens = out_hc->bytes / hc_row_bytes;
    if (n_tokens == 0 || n_tokens > UINT32_MAX ||
        n_tokens > UINT64_MAX / fixed_n_embd ||
        n_tokens > UINT64_MAX / mix_hc ||
        n_tokens > UINT64_MAX / hc_row_elems ||
        n_tokens > UINT64_MAX / fixed_n_expert) {
        return 0;
    }
    const uint64_t block_elems = n_tokens * fixed_n_embd;
    const uint64_t routed_elems =
        n_tokens * fixed_n_expert * fixed_n_embd;
    const uint64_t split_elems = n_tokens * mix_hc;
    const uint64_t hc_elems = n_tokens * hc_row_elems;
    if (routed_out->bytes < block_elems * sizeof(float) ||
        routed_down->bytes < routed_elems * sizeof(float) ||
        shared_out->bytes < block_elems * sizeof(float) ||
        residual_hc->bytes < hc_elems * sizeof(float) ||
        split->bytes < split_elems * sizeof(float) ||
        norm_h->bytes < hc_elems * sizeof(__half)) {
        return 0;
    }

    hc_expand_routed_sum_add_split_rms_f16_kernel
        <<<(uint32_t)n_tokens, 256>>>(
            (float *)out_hc->ptr,
            (__half *)norm_h->ptr,
            (const float *)routed_down->ptr,
            (const float *)shared_out->ptr,
            (const float *)residual_hc->ptr,
            (const float *)split->ptr,
            (uint32_t)n_tokens,
            eps);
    const cudaError_t fused_err = cudaGetLastError();
    if (fused_err == cudaSuccess) return 1;

    /* A deferred routed launch has deliberately left routed_out unwritten.
     * Recover the old exact pipeline locally if this specialization cannot
     * launch, so callers never have to guess whether the sum exists. */
    fprintf(stderr,
            "ds4: hc routed-sum fusion unavailable (%s); using exact fallback\n",
            cudaGetErrorString(fused_err));
    moe_sum_kernel<<<(block_elems + 255u) / 256u, 256>>>(
        (float *)routed_out->ptr,
        (const float *)routed_down->ptr,
        (uint32_t)fixed_n_embd,
        (uint32_t)fixed_n_expert,
        (uint32_t)n_tokens);
    if (!cuda_ok(cudaGetLastError(),
                 "hc routed-sum fallback sum launch")) {
        return 0;
    }
    return cuda_hc_expand_split_rms_f16_tensor(
        out_hc, norm_h, routed_out, shared_out, residual_hc, split,
        (uint32_t)fixed_n_embd, (uint32_t)fixed_n_hc, eps);
}

extern "C" int ds4_gpu_hc_expand_split_half_tensor(
        ds4_gpu_tensor *out_hc,
        const ds4_gpu_tensor *block_out_h,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t n_embd,
        uint32_t n_hc) {
    (void)out_hc; (void)block_out_h; (void)residual_hc; (void)split;
    (void)n_embd; (void)n_hc;
    return 0;
}

extern "C" int ds4_gpu_hc_expand_add_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !block_add || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_add->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 1);
    return cuda_ok(cudaGetLastError(), "hc_expand_add_split launch");
}

extern "C" int ds4_gpu_hc_expand_add_split_half_add_tensor(
